documents.template_local:
yamaa: "1.0"
type: spec
domain: TEST
keys: [T, I]
input: {SRC: {path: input.csv, types: {I: int, O: int}}}
columns:
  - {name: T, type: str}
  - {name: I, type: int, derivation: SRC.I}
  - {name: N, type: int}
rows:
  - id: first
    dataset: SRC
    derivations:
      T: "'A'"
      N: {case: [{when: 'I > 0', then: {row_number: {window: {order_by: [SRC.O]}}}}]}
  - id: second
    dataset: SRC
    filter: 'SRC.I > 1'
    derivations:
      T: "'B'"
      N: {case: [{when: 'I > 0', then: {row_number: {window: {order_by: [SRC.O]}}}}]}
output: {path: out.csv, columns: [T, I, N]}

documents.baseline_branch:
yamaa: "1.0"
type: spec
domain: TEST
keys: [I]
input: {SRC: {path: input.csv, types: {I: int, D: date}}}
columns:
  - {name: I, type: int, derivation: SRC.I}
  - {name: D, type: date, derivation: SRC.D}
  - name: B
    type: str
    derivation:
      case:
        - when: 'I < 0'
          then: {baseline_flag: {date: D, reference: D, source: I}}
        - otherwise: "'skipped'"
output: {path: out.csv, columns: [I, B]}

documents.wide_offsets:
yamaa: "1.0"
type: spec
domain: TEST
keys: [I]
input: {SRC: input.csv}
columns:
  - {name: I, type: int, derivation: SRC.I}
  - {name: V, type: str, derivation: SRC.V}
  - name: BEFORE
    type: str
    derivation: {row_value: {source: V, offset: -99999999999999999999999999999999999999, window: {order_by: [I]}}}
  - name: AFTER
    type: str
    derivation: {row_value: {source: V, offset: 99999999999999999999999999999999999999, window: {order_by: [I]}}}
output: {path: out.csv, columns: [I, BEFORE, AFTER]}

documents.grouped_baseline:
yamaa: "1.0"
type: spec
domain: TEST
keys: [I]
input: {SRC: {path: input.csv, types: {I: int, D: date}}}
columns:
  - {name: I, type: int, derivation: SRC.I}
  - {name: G, type: str, derivation: SRC.G}
  - {name: D, type: date, derivation: SRC.D}
  - name: B
    type: str
    derivation:
      case:
        - when: "G = 'A'"
          then: {baseline_flag: {date: D, reference: D, source: I, window: {group_by: [G]}}}
        - otherwise: "'skipped'"
output: {path: out.csv, columns: [I, B]}

documents.named:
yamaa: "1.0"
type: spec
domain: OUT
base: SRC
keys: [ID]
input: {SRC: {path: input.csv, types: {SEQ: int, VAL: int}}}
output: {path: out.csv, columns: [ID, PREV]}
windows:
  VISITS: {group_by: [G], order_by: [SEQ]}
columns:
  - {name: ID, type: str, label: ID, derivation: SRC.ID}
  - {name: G, type: str, label: G, derivation: SRC.G}
  - {name: SEQ, type: int, label: SEQ, derivation: SRC.SEQ}
  - {name: VAL, type: int, label: VAL, derivation: SRC.VAL}
  - {name: PREV, type: int, label: 'Previous value', derivation: {row_value: {source: VAL, offset: -1, window: VISITS}}}

documents.named_rows:
yamaa: "1.0"
type: spec
domain: OUT
base: SRC
keys: [ID]
input: {SRC: {path: input.csv, types: {SEQ: int, VAL: int}}}
output: {path: out.csv, columns: [ID, PREV]}
windows:
  VISITS: {order_by: [SEQ]}
columns:
  - {name: ID, type: str, label: ID}
  - {name: G, type: str, label: G}
  - {name: SEQ, type: int, label: SEQ}
  - {name: VAL, type: int, label: VAL}
  - {name: PREV, type: int, label: 'Previous value'}
rows:
  - id: a
    dataset: SRC
    filter: "SRC.G = 'a'"
    derivations: {ID: SRC.ID, G: SRC.G, SEQ: SRC.SEQ, VAL: SRC.VAL, PREV: {row_value: {source: VAL, offset: -1, window: VISITS}}}
  - id: b
    dataset: SRC
    filter: "SRC.G = 'b'"
    derivations: {ID: SRC.ID, G: SRC.G, SEQ: SRC.SEQ, VAL: SRC.VAL, PREV: {row_value: {source: VAL, offset: -1, window: VISITS}}}

documents.numbering:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {ID: int, V: int}}}
windows:
  ORDER: {group_by: [G], order_by: [{variable: V, direction: desc, nulls: last}]}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: G, type: str, derivation: SRC.G}
  - {name: V, type: int, derivation: SRC.V}
  - {name: SEQ, type: int, derivation: {row_number: {window: ORDER}}}
  - {name: RANK, type: int, derivation: {rank: {window: ORDER}}}
  - {name: DENSE, type: int, derivation: {rank: {method: dense, window: ORDER}}}
output: {path: out.csv, columns: [ID, G, V, SEQ, RANK, DENSE]}

documents.filter_and:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {ID: int, V: int}}}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: V, type: int, derivation: SRC.V}
  - name: SEQ
    type: int
    derivation: {row_number: {window: {order_by: [V], filter: "FALSE AND V > 'x'"}}}
output: {path: out.csv, columns: [ID, V, SEQ]}

documents.eligibility:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {ID: int, ELIGIBLE: int, ADT: date, TRTSDT: date}}}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: G, type: str, derivation: SRC.G}
  - {name: ELIGIBLE, type: int, derivation: SRC.ELIGIBLE}
  - {name: ADT, type: date, derivation: SRC.ADT}
  - {name: TRTSDT, type: date, derivation: SRC.TRTSDT}
  - name: BLFL
    type: str
    derivation:
      baseline_flag: {date: ADT, reference: TRTSDT, source: ID, window: {filter: 'ELIGIBLE > 0'}}
output: {path: out.csv, columns: [ID, BLFL]}

documents.tie_break:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {ID: int, ADT: date, TRTSDT: date, TM: int, SEQ: int}}}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: G, type: str, derivation: SRC.G}
  - {name: ADT, type: date, derivation: SRC.ADT}
  - {name: TRTSDT, type: date, derivation: SRC.TRTSDT}
  - {name: TM, type: int, derivation: SRC.TM}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - name: BLFL
    type: str
    derivation:
      baseline_flag: {date: ADT, reference: TRTSDT, source: ID, window: {group_by: [G], order_by: [ADT, {variable: TM, direction: desc}]}}
output: {path: out.csv, columns: [ID, BLFL]}
